import com.github.javaparser.JavaParser;
import com.github.javaparser.ast.CompilationUnit;
import com.github.javaparser.ast.expr.MethodCallExpr;
import com.github.javaparser.ast.visitor.VoidVisitorAdapter;
import com.github.javaparser.resolution.declarations.ResolvedMethodDeclaration;
import com.github.javaparser.resolution.model.SymbolReference;
import com.github.javaparser.symbolsolver.javaparsermodel.JavaParserFacade;
import com.github.javaparser.symbolsolver.resolution.typesolvers.ReflectionTypeSolver;

public class TestTextBlock {
    public static void main(String[] args) {
        String fileContent = "package my.example;\n"
                + "public class MyExample {\n"
                + "  public static void main(String[] args) {\n"
                + "    \"Hello single %s!\".formatted(\"world\");\n"
                + "    \"\"\"\n"
                + "        Hello multiple %s!\n"
                + "        \"\"\".formatted(\"world\");\n"
                + "  }\n"
                + "}\n";
        ReflectionTypeSolver solver = new ReflectionTypeSolver(false);
        CompilationUnit cu = new JavaParser().parse(fileContent).getResult().get();
        new VoidVisitorAdapter<Object>() {
            public void visit(MethodCallExpr n, Object arg) {
                super.visit(n, arg);
                try {
                    SymbolReference<ResolvedMethodDeclaration> solved =
                            JavaParserFacade.get(solver).solve(n.asMethodCallExpr());
                    System.out.println("Could solve: " + n + " as "
                            + solved.getCorrespondingDeclaration().getQualifiedSignature());
                } catch (Exception e) {
                    System.err.println("Could not solve: " + n);
                    e.printStackTrace();
                }
            }
        }.visit(cu.getTypes(), null);
    }
}

